CREATE FUNCTION crm_audience_v2.selection_canonical(v jsonb, depth integer DEFAULT 0)
RETURNS text LANGUAGE plpgsql IMMUTABLE SECURITY INVOKER SET search_path=pg_catalog AS $fn$
DECLARE out text; k text; x jsonb; parts text[]:=ARRAY[]::text[];
BEGIN
 IF v IS NULL OR depth>12 OR octet_length(v::text)>64000 THEN RETURN NULL; END IF;
 CASE jsonb_typeof(v)
 WHEN 'object' THEN
  FOR k,x IN SELECT key,value FROM jsonb_each(v) ORDER BY key COLLATE "C" LOOP
   IF k !~ '^[a-z_]+$' THEN RETURN NULL; END IF;
   out:=crm_audience_v2.selection_canonical(x,depth+1); IF out IS NULL THEN RETURN NULL; END IF;
   parts:=array_append(parts,to_jsonb(k)::text||':'||out);
  END LOOP;
  RETURN '{'||array_to_string(parts,',')||'}';
 WHEN 'array' THEN
  FOR x IN SELECT value FROM jsonb_array_elements(v) LOOP
   out:=crm_audience_v2.selection_canonical(x,depth+1); IF out IS NULL THEN RETURN NULL; END IF;
   parts:=array_append(parts,out);
  END LOOP;
  RETURN '['||array_to_string(parts,',')||']';
 WHEN 'number' THEN
  IF v::text !~ '^(0|[1-9][0-9]*)$' THEN RETURN NULL; END IF;
  RETURN v::text;
 WHEN 'string','boolean','null' THEN RETURN v::text;
 ELSE RETURN NULL;
 END CASE;
END $fn$;

CREATE OR REPLACE FUNCTION crm_audience_v2.selection_catalog_valid(raw jsonb,brand text) RETURNS boolean
LANGUAGE plpgsql STABLE SECURITY INVOKER SET search_path=pg_catalog AS $fn$
DECLARE x jsonb; seen text[]:=ARRAY[]::text[];
BEGIN
 IF jsonb_typeof(raw) IS DISTINCT FROM 'object'
  OR NOT(raw ?& ARRAY['currency','timezone','shop_id','fields','products','origins'])
  OR raw-'currency'-'timezone'-'shop_id'-'fields'-'products'-'origins'-'recorded_origins'<>'{}'::jsonb THEN RETURN false; END IF;
 IF raw->'currency'<>'null'::jsonb AND (jsonb_typeof(raw->'currency')<>'string' OR raw->>'currency' !~ '^[A-Z]{3}$') THEN RETURN false; END IF;
 IF raw->'shop_id'<>'null'::jsonb AND (jsonb_typeof(raw->'shop_id')<>'string' OR raw->>'shop_id' !~ '^gid://shopify/Shop/[1-9][0-9]{0,19}$') THEN RETURN false; END IF;
 IF raw->'timezone'<>'null'::jsonb AND (jsonb_typeof(raw->'timezone')<>'string'
  OR NOT EXISTS(SELECT 1 FROM crm_audience_v2.selection_timezone WHERE name=raw->>'timezone')) THEN RETURN false; END IF;
 IF jsonb_typeof(raw->'fields')<>'array' OR jsonb_typeof(raw->'products')<>'array' OR jsonb_typeof(raw->'origins')<>'array' THEN RETURN false; END IF;
 IF jsonb_array_length(raw->'fields')>8 OR jsonb_array_length(raw->'products')>1000 OR jsonb_array_length(raw->'origins')>3 THEN RETURN false; END IF;
 FOR x IN SELECT value FROM jsonb_array_elements(raw->'fields') LOOP
  IF jsonb_typeof(x) IS DISTINCT FROM 'object' OR NOT(x ?& ARRAY['key','available','source_hash']) OR x-'key'-'available'-'source_hash'<>'{}'::jsonb
   OR x->>'key' NOT IN('purchase.count','purchase.last_date','purchase.amount','purchase.product','signup.origin','signup.recorded_origin','email.opened','email.clicked')
   OR jsonb_typeof(x->'key')<>'string' OR (x->>'key')=ANY(seen) OR jsonb_typeof(x->'available')<>'boolean'
   OR (x->'source_hash'<>'null'::jsonb AND (jsonb_typeof(x->'source_hash')<>'string' OR x->>'source_hash' !~ '^[0-9a-f]{64}$'))
   OR (x->'available'='true'::jsonb AND x->'source_hash'='null'::jsonb) THEN RETURN false; END IF;
  seen:=array_append(seen,x->>'key');
 END LOOP;
 seen:=ARRAY[]::text[];
 FOR x IN SELECT value FROM jsonb_array_elements(raw->'products') LOOP
  IF jsonb_typeof(x) IS DISTINCT FROM 'object' OR NOT(x ?& ARRAY['id','brand','name','available']) OR x-'id'-'brand'-'name'-'available'<>'{}'::jsonb
   OR x->>'brand' IS DISTINCT FROM brand OR jsonb_typeof(x->'id')<>'string' OR x->>'id' !~ '^gid://shopify/Product/[1-9][0-9]{0,19}$'
   OR (x->>'id')=ANY(seen) OR jsonb_typeof(x->'name')<>'string' OR crm_audience_v2.selection_utf16_length(x->>'name')>500 OR jsonb_typeof(x->'available')<>'boolean' THEN RETURN false; END IF;
  seen:=array_append(seen,x->>'id');
 END LOOP;
 seen:=ARRAY[]::text[];
 FOR x IN SELECT value FROM jsonb_array_elements(raw->'origins') LOOP
  IF jsonb_typeof(x) IS DISTINCT FROM 'object' OR NOT(x ?& ARRAY['key','brand','name','available','provenance_hash']) OR x-'key'-'brand'-'name'-'available'-'provenance_hash'<>'{}'::jsonb
   OR x->>'brand' IS DISTINCT FROM brand OR jsonb_typeof(x->'key')<>'string' OR x->>'key' NOT IN('popup','vip_alma','vip_desodorante')
   OR (x->>'key')=ANY(seen) OR jsonb_typeof(x->'name')<>'string' OR crm_audience_v2.selection_utf16_length(x->>'name')>500 OR jsonb_typeof(x->'available')<>'boolean'
   OR (x->'provenance_hash'<>'null'::jsonb AND (jsonb_typeof(x->'provenance_hash')<>'string' OR x->>'provenance_hash' !~ '^[0-9a-f]{64}$'))
   OR (x->'available'='true'::jsonb AND x->'provenance_hash'='null'::jsonb) THEN RETURN false; END IF;
  seen:=array_append(seen,x->>'key');
 END LOOP;
 seen:=ARRAY[]::text[];
 IF raw ? 'recorded_origins' THEN
  IF jsonb_typeof(raw->'recorded_origins') IS DISTINCT FROM 'array' OR jsonb_array_length(raw->'recorded_origins')>2 THEN RETURN false; END IF;
  FOR x IN SELECT value FROM jsonb_array_elements(raw->'recorded_origins') LOOP
   IF jsonb_typeof(x) IS DISTINCT FROM 'object'
    OR NOT(x ?& ARRAY['key','brand','name','available','scope_id','producer_id','producer_revision','coverage_started_at','provenance_hash'])
    OR x-'key'-'brand'-'name'-'available'-'scope_id'-'producer_id'-'producer_revision'-'coverage_started_at'-'provenance_hash'<>'{}'::jsonb
    OR brand<>'aristo' OR x->>'brand' IS DISTINCT FROM brand OR x->>'key' NOT IN('vip_alma','vip_desodorante')
    OR jsonb_typeof(x->'key')<>'string' OR (x->>'key')=ANY(seen)
    OR jsonb_typeof(x->'name')<>'string' OR crm_audience_v2.selection_utf16_length(x->>'name') NOT BETWEEN 1 AND 500 OR x->>'name' ~ '[[:cntrl:]]'
    OR jsonb_typeof(x->'available')<>'boolean' OR jsonb_typeof(x->'scope_id')<>'string' OR x->>'scope_id' !~ '^[a-f0-9]{8}-[a-f0-9]{4}-[a-f0-9]{4}-[a-f0-9]{4}-[a-f0-9]{12}$'
    OR x->>'producer_id' IS DISTINCT FROM (CASE x->>'key' WHEN 'vip_alma' THEN 'NAmTWZ7vddQ8LX1k' WHEN 'vip_desodorante' THEN 'ywJDsgBDhZOBgoxb' END)
    OR jsonb_typeof(x->'producer_revision')<>'string' OR x->>'producer_revision' !~ '^[a-f0-9]{64}$'
    OR jsonb_typeof(x->'coverage_started_at')<>'string' OR x->>'coverage_started_at' !~ '^[0-9]{4}-[0-9]{2}-[0-9]{2}T[0-9]{2}:[0-9]{2}:[0-9]{2}[.][0-9]{3}Z$'
    OR to_char((x->>'coverage_started_at')::timestamptz AT TIME ZONE 'UTC','YYYY-MM-DD"T"HH24:MI:SS.MS"Z"') IS DISTINCT FROM x->>'coverage_started_at'
    OR jsonb_typeof(x->'provenance_hash')<>'string' OR x->>'provenance_hash' !~ '^[a-f0-9]{64}$'
    OR x->>'provenance_hash' IS DISTINCT FROM crm_audience_v2.selection_hash(jsonb_build_object(
     'contract','crm-recorded-origin-exists-v1','brand',brand,'origin',x->>'key','scope_id',x->>'scope_id',
     'producer_id',x->>'producer_id','producer_revision',x->>'producer_revision','coverage_started_at',x->>'coverage_started_at')) THEN RETURN false; END IF;
   seen:=array_append(seen,x->>'key');
  END LOOP;
 END IF;
 RETURN true;
EXCEPTION WHEN invalid_datetime_format OR datetime_field_overflow THEN RETURN false;
END $fn$;

CREATE FUNCTION crm_audience_v2.selection_engagement_match(rule jsonb,sid integer,brand text) RETURNS boolean
LANGUAGE plpgsql STABLE SECURITY INVOKER SET search_path=pg_catalog AS $fn$
DECLARE matched boolean; days integer; cutoff timestamptz;
BEGIN
 IF jsonb_typeof(rule) IS DISTINCT FROM 'object' OR rule->>'op' IS DISTINCT FROM 'condition'
  OR NOT(rule ?& ARRAY['op','field','operator','value']) OR rule-'op'-'field'-'operator'-'value'<>'{}'::jsonb
  OR jsonb_typeof(rule->'field') IS DISTINCT FROM 'string' OR jsonb_typeof(rule->'operator') IS DISTINCT FROM 'string'
  OR rule->>'field' NOT IN('email.opened','email.clicked')
  OR rule->>'operator' NOT IN('within_last_days','not_within_last_days')
  OR jsonb_typeof(rule->'value') IS DISTINCT FROM 'number' OR rule->>'value' !~ '^[1-9][0-9]{0,3}$'
  OR (rule->>'value')::numeric>3650 OR brand IS NULL OR brand NOT IN('fish','aristo') THEN RETURN NULL; END IF;
 days:=(rule->>'value')::integer;
 cutoff:=statement_timestamp()-(days::double precision*86400*interval '1 second');
 IF rule->>'field'='email.opened' THEN
  SELECT EXISTS(SELECT 1 FROM public.campaign_views ev JOIN public.campaigns ec ON ec.id=ev.campaign_id
   WHERE ev.subscriber_id=sid AND ec.attribs#>>'{crm,policy}'='crm-campaign-v1' AND ec.attribs#>>'{crm,brand}'=brand
    AND ec.messenger::text='email' AND ec.type::text='regular'
    AND ev.created_at>=cutoff AND ev.created_at<=statement_timestamp()) INTO matched;
 ELSE
  SELECT EXISTS(SELECT 1 FROM public.link_clicks ev JOIN public.campaigns ec ON ec.id=ev.campaign_id
   WHERE ev.subscriber_id=sid AND ec.attribs#>>'{crm,policy}'='crm-campaign-v1' AND ec.attribs#>>'{crm,brand}'=brand
    AND ec.messenger::text='email' AND ec.type::text='regular'
    AND ev.created_at>=cutoff AND ev.created_at<=statement_timestamp()) INTO matched;
 END IF;
 RETURN CASE WHEN rule->>'operator'='within_last_days' THEN matched ELSE NOT matched END;
END $fn$;

CREATE OR REPLACE FUNCTION crm_audience_v2.selection_rule(rule jsonb,sid integer,brand text,depth integer DEFAULT 1,source_config jsonb DEFAULT NULL)
RETURNS jsonb LANGUAGE plpgsql STABLE SECURITY INVOKER SET search_path=pg_catalog AS $fn$
DECLARE child jsonb; result jsonb; matches boolean; nodes integer:=1;
 pins jsonb:='[]'::jsonb; selected_list_id integer; native_optin text; source_hash text;
BEGIN
 IF depth<1 OR depth>4 OR jsonb_typeof(rule) IS DISTINCT FROM 'object' THEN RETURN NULL; END IF;
 IF rule->>'op'='confirmed' THEN
  IF rule-'op'-'rule'<>'{}'::jsonb OR NOT(rule ?& ARRAY['op','rule']) OR NOT crm_audience_v2.shopify_rule_valid(rule->'rule') THEN RETURN NULL; END IF;
  result:=crm_audience_v2.selection_rule(rule->'rule',sid,brand,depth+1,source_config);
  IF result IS NULL OR (result->>'nodes')::integer+1>32 THEN RETURN NULL; END IF;
  RETURN result||jsonb_build_object('match',coalesce((result->>'match')::boolean,false),'nodes',(result->>'nodes')::integer+1);
 END IF;
 IF rule->>'op'='in_list' THEN
  IF rule-'op'-'list_id'<>'{}'::jsonb OR NOT(rule ?& ARRAY['op','list_id'])
   OR jsonb_typeof(rule->'list_id') IS DISTINCT FROM 'number'
   OR (rule->>'list_id') !~ '^[1-9][0-9]{0,9}$'
   OR (rule->>'list_id')::numeric>2147483647 THEN RETURN NULL; END IF;
  selected_list_id:=(rule->>'list_id')::integer;
  SELECT l.optin::text INTO native_optin FROM public.lists l
   WHERE l.id=selected_list_id AND l.status::text='active'
   AND public.shrigma_campaign_list_brand(l)=brand AND l.optin::text IN('single','double');
  IF NOT FOUND THEN RETURN NULL; END IF;
  SELECT EXISTS(SELECT 1 FROM public.subscriber_lists sl WHERE sl.subscriber_id=sid AND sl.list_id=selected_list_id
   AND ((native_optin='double' AND sl.status::text='confirmed')
    OR (native_optin='single' AND sl.status::text IN('confirmed','unconfirmed')))) INTO matches;
  RETURN jsonb_build_object('match',matches,'nodes',1,'pins',jsonb_build_array(jsonb_build_object(
   'rule_key','{"op":"in_list","list_id":'||selected_list_id||'}','list_id',selected_list_id,'optin',native_optin)));
 END IF;
 IF rule->>'op'='condition' THEN
  -- Legacy combined callers pass no source configuration and stay list-only.
  IF source_config IS NULL THEN RETURN NULL; END IF;
  IF rule->>'field' IN('purchase.count','purchase.amount','purchase.last_date','purchase.product') THEN
   RETURN crm_audience_v2.selection_shopify_rule(rule,sid,brand,source_config);
  END IF;
  IF rule->>'field'='signup.recorded_origin' THEN RETURN crm_audience_v2.selection_recorded_origin_rule(rule,sid,brand,source_config); END IF;
  source_hash:=crm_audience_v2.selection_engagement_source_hash(brand,rule->>'field');
  IF source_hash IS NULL OR (SELECT count(*) FROM jsonb_array_elements(source_config->'fields') f
   WHERE f->>'key'=rule->>'field' AND f->'available'='true'::jsonb AND f->>'source_hash'=source_hash)<>1 THEN RETURN NULL; END IF;
  matches:=crm_audience_v2.selection_engagement_match(rule,sid,brand);
  IF matches IS NULL THEN RETURN NULL; END IF;
  RETURN jsonb_build_object('match',matches,'nodes',1,'pins',jsonb_build_array(jsonb_build_object(
   'rule_key','{"op":"condition","field":'||to_jsonb(rule->>'field')::text||',"operator":'||to_jsonb(rule->>'operator')::text||',"value":'||(rule->>'value')||'}',
   'source','email','source_hash',source_hash)));
 END IF;
 IF rule->>'op' NOT IN('and','or') OR rule->>'op' IS NULL
  OR rule-'op'-'rules'<>'{}'::jsonb OR jsonb_typeof(rule->'rules') IS DISTINCT FROM 'array' THEN RETURN NULL; END IF;
 IF jsonb_array_length(rule->'rules')<1 OR jsonb_array_length(rule->'rules')>16 THEN RETURN NULL; END IF;
 matches:=rule->>'op'='and';
 FOR child IN SELECT value FROM jsonb_array_elements(rule->'rules') LOOP
  result:=crm_audience_v2.selection_rule(child,sid,brand,depth+1,source_config);
  IF result IS NULL THEN RETURN NULL; END IF;
  nodes:=nodes+(result->>'nodes')::integer; IF nodes>32 THEN RETURN NULL; END IF;
  pins:=pins||(result->'pins');
  IF rule->>'op'='and' THEN matches:=matches AND (result->>'match')::boolean;
  ELSE matches:=matches OR (result->>'match')::boolean; END IF;
 END LOOP;
 RETURN jsonb_build_object('match',matches,'nodes',nodes,'pins',pins);
END $fn$;

CREATE OR REPLACE FUNCTION crm_audience_v2.selection_context(cid integer,expected_query_sha256 text,native_engagement boolean DEFAULT false) RETURNS jsonb
LANGUAGE plpgsql STABLE SECURITY INVOKER SET search_path=pg_catalog AS $fn$
DECLARE b crm_audience_v2.campaign_binding%ROWTYPE; r crm_audience_v2.revision%ROWTYPE;
 c crm_audience_v2.config%ROWTYPE; result jsonb; base_result jsonb; current_context jsonb;
 current_pins jsonb; seen_at timestamptz:=statement_timestamp();
BEGIN
 SELECT * INTO b FROM crm_audience_v2.campaign_binding_effective(cid);
 IF NOT FOUND THEN RETURN jsonb_build_object('bound',false); END IF; -- Preserve unbound native selection.
 IF NOT EXISTS(SELECT 1 FROM crm_audience_v2.selection_runtime rt WHERE rt.singleton AND rt.enabled
  AND rt.candidate_query_sha256=expected_query_sha256
  AND isfinite(rt.verified_at) AND rt.verified_at<=seen_at AND rt.verified_at>seen_at-interval '5 minutes') THEN RETURN NULL; END IF;
 SELECT * INTO r FROM crm_audience_v2.revision WHERE audience_id=b.audience_id AND version=b.audience_revision;
 IF NOT FOUND OR r.archived OR r.definition_hash IS DISTINCT FROM b.definition_hash OR r.context_hash IS DISTINCT FROM b.context_hash
  OR crm_audience_v2.selection_hash(r.definition) IS DISTINCT FROM b.definition_hash
  OR crm_audience_v2.selection_hash(r.context) IS DISTINCT FROM b.context_hash
  OR r.definition->>'schema_version' IS DISTINCT FROM 'crm-audience-v2' OR r.definition->>'brand' IS DISTINCT FROM b.brand
  OR r.definition-'schema_version'-'brand'-'name'-'rule'<>'{}'::jsonb
  OR NOT(r.definition ?& ARRAY['schema_version','brand','name','rule']) THEN RETURN NULL; END IF;
 IF NOT EXISTS(SELECT 1 FROM crm_audience_v2.audience a WHERE a.id=b.audience_id AND a.brand=b.brand AND NOT a.archived) THEN RETURN NULL; END IF;
 IF b.binding->>'contract' IS DISTINCT FROM 'crm-audience-campaign-binding-v1'
  OR b.binding->'definition' IS DISTINCT FROM r.definition OR b.binding->'context' IS DISTINCT FROM r.context
  OR crm_audience_v2.selection_hash(b.binding) IS DISTINCT FROM b.binding_hash
  OR b.binding->>'brand' IS DISTINCT FROM b.brand
  OR b.binding->'campaign_id' IS DISTINCT FROM to_jsonb(b.campaign_id)
  OR b.binding->'binding_version' IS DISTINCT FROM to_jsonb(b.binding_version)
  OR b.binding->>'audience_id' IS DISTINCT FROM b.audience_id::text
  OR b.binding->'audience_revision' IS DISTINCT FROM to_jsonb(b.audience_revision)
  OR b.binding->>'definition_hash' IS DISTINCT FROM b.definition_hash
  OR b.binding->>'context_hash' IS DISTINCT FROM b.context_hash
  OR b.binding->'base_list_id' IS DISTINCT FROM to_jsonb(b.base_list_id)
  OR b.binding->>'campaign_version' IS DISTINCT FROM b.campaign_version
  OR b.binding->>'catalog_hash' IS DISTINCT FROM b.catalog_hash
  OR b.binding->'authorizes_selection' IS DISTINCT FROM 'false'::jsonb
  OR b.binding->'authorizes_send' IS DISTINCT FROM 'false'::jsonb THEN RETURN NULL; END IF;
 IF NOT EXISTS(SELECT 1 FROM crm_audience_v2.campaign_binding_revision h WHERE h.campaign_id=cid
  AND h.binding_version=b.binding_version AND h.binding=b.binding AND h.binding_hash=b.binding_hash) THEN RETURN NULL; END IF;
 IF NOT EXISTS(SELECT 1 FROM public.campaigns ca WHERE ca.id=cid AND ca.type::text='regular'
  AND ca.messenger::text='email' AND ca.attribs#>>'{crm,brand}'=b.brand) THEN RETURN NULL; END IF;
 -- Native enumeration must cover exactly the brand base, not an arbitrary
 -- native union that would silently narrow an OR audience before this filter.
 IF (SELECT array_agg(cl.list_id ORDER BY cl.list_id) FROM public.campaign_lists cl WHERE cl.campaign_id=cid)
  IS DISTINCT FROM ARRAY[b.base_list_id] THEN RETURN NULL; END IF;
 SELECT * INTO c FROM crm_audience_v2.config WHERE brand=b.brand;
 IF NOT FOUND OR NOT c.enabled OR c.base_list_id IS DISTINCT FROM b.base_list_id OR c.catalog IS NULL
  OR c.checked_at IS NULL OR c.expires_at IS NULL
  OR NOT isfinite(c.checked_at) OR NOT isfinite(c.expires_at) OR c.checked_at>seen_at OR c.expires_at<=seen_at
  OR c.expires_at>c.checked_at+interval '5 minutes'
  OR NOT crm_audience_v2.selection_catalog_valid(c.catalog,b.brand)
  OR NOT crm_audience_v2.selection_lists_valid(b.brand) THEN RETURN NULL; END IF;
 result:=crm_audience_v2.selection_rule(r.definition->'rule',0,b.brand,1,CASE WHEN native_engagement THEN c.catalog ELSE NULL END);
 base_result:=crm_audience_v2.selection_rule(jsonb_build_object('op','in_list','list_id',b.base_list_id),0,b.brand);
 IF result IS NULL OR base_result IS NULL THEN RETURN NULL; END IF;
 SELECT jsonb_agg(p ORDER BY (p->>'rule_key') COLLATE "C") INTO current_pins
  FROM (SELECT DISTINCT value AS p FROM jsonb_array_elements(result->'pins')) q;
 current_context:=jsonb_build_object('contract','crm-audience-context-v1','hash_contract','canonical-json-sorted-keys-sha256-v1',
  'brand',b.brand,'base',jsonb_build_object('id',b.base_list_id,'brand',b.brand,'optin',base_result#>>'{pins,0,optin}'),'rules',current_pins);
 IF current_context IS DISTINCT FROM r.context OR crm_audience_v2.selection_hash(current_context) IS DISTINCT FROM b.context_hash THEN RETURN NULL; END IF;
 RETURN jsonb_build_object('bound',true,'brand',b.brand,'base_list_id',b.base_list_id,'definition',r.definition,
  'shopify_expires_at',CASE WHEN EXISTS(SELECT 1 FROM jsonb_array_elements(current_pins) p WHERE p->>'source'='shopify')
   THEN crm_audience_v2.shopify_snapshot(b.brand)->'expires_at' END,
  'list_pins',(SELECT jsonb_agg(pin) FROM jsonb_array_elements(current_pins||(base_result->'pins')) pin WHERE pin ? 'list_id'));
END $fn$;

CREATE OR REPLACE FUNCTION crm_audience_v2.selection_regular_rule_match(rule jsonb,consented integer[],sid integer,brand text) RETURNS boolean
 LANGUAGE plpgsql STABLE SECURITY INVOKER SET search_path=pg_catalog AS $fn$
 DECLARE child jsonb; matched boolean; result boolean; pin text;
 BEGIN
  IF rule->>'op'='confirmed' THEN
   IF rule-'op'-'rule'<>'{}'::jsonb OR NOT(rule ?& ARRAY['op','rule']) OR NOT crm_audience_v2.shopify_rule_valid(rule->'rule') THEN RAISE EXCEPTION USING ERRCODE='55000',MESSAGE='SEGMENT_SELECTION_UNAVAILABLE'; END IF;
   SELECT field_hashes->>(rule#>>'{rule,field}') INTO pin FROM crm_audience_v2.shopify_source WHERE shopify_source.brand=selection_regular_rule_match.brand;
   IF NOT crm_audience_v2.shopify_source_current(brand,rule#>>'{rule,field}',pin) THEN RAISE EXCEPTION USING ERRCODE='55000',MESSAGE='SEGMENT_SELECTION_UNAVAILABLE'; END IF;
   RETURN coalesce(crm_audience_v2.shopify_customer_match(rule->'rule',sid,brand,pin),false);
  END IF;
  IF rule->>'op'='in_list' THEN RETURN (rule->>'list_id')::integer=ANY(consented); END IF;
  IF rule->>'op'='condition' THEN
   IF rule->>'field' IN('purchase.count','purchase.amount','purchase.last_date','purchase.product') THEN
    SELECT field_hashes->>(rule->>'field') INTO pin FROM crm_audience_v2.shopify_source WHERE shopify_source.brand=selection_regular_rule_match.brand;
    RETURN crm_audience_v2.shopify_customer_match(rule,sid,brand,pin);
   END IF;
   IF rule->>'field'='signup.recorded_origin' THEN
    SELECT crm_audience_v2.recorded_origin_descriptor(s)->>'provenance_hash' INTO pin FROM crm_audience_v2.recorded_origin_source s WHERE s.brand=selection_regular_rule_match.brand AND s.canonical_origin=rule->>'value' AND s.enabled;
    RETURN crm_audience_v2.recorded_origin_match(rule,sid,brand,pin);
   END IF;
   matched:=crm_audience_v2.selection_engagement_match(rule,sid,brand);
   IF matched IS NULL THEN RAISE EXCEPTION USING ERRCODE='55000',MESSAGE='SEGMENT_SELECTION_UNAVAILABLE'; END IF;
   RETURN matched;
  END IF;
  IF rule->>'op' NOT IN('and','or') OR rule->>'op' IS NULL THEN
   RAISE EXCEPTION USING ERRCODE='55000',MESSAGE='SEGMENT_SELECTION_UNAVAILABLE';
  END IF;
  result:=rule->>'op'='and';
  FOR child IN SELECT value FROM jsonb_array_elements(rule->'rules') LOOP
   matched:=crm_audience_v2.selection_regular_rule_match(child,consented,sid,brand);
   IF rule->>'op'='and' THEN result:=result AND matched; ELSE result:=result OR matched; END IF;
  END LOOP;
  RETURN result;
 END $fn$;

CREATE OR REPLACE FUNCTION crm_audience_v2.selection_regular_matches(ctx jsonb,sid integer) RETURNS boolean
 LANGUAGE plpgsql STABLE SECURITY INVOKER SET search_path=pg_catalog AS $fn$
 DECLARE consented integer[]; matched boolean;
 BEGIN
  IF ctx IS NULL THEN RAISE EXCEPTION USING ERRCODE='55000',MESSAGE='SEGMENT_SELECTION_UNAVAILABLE'; END IF;
  IF ctx->'bound'='false'::jsonb THEN RETURN true; END IF;
  IF ctx ? 'ab_test_id' AND NOT EXISTS(SELECT 1 FROM public.crm_ab_member_v2
   WHERE test_id=(ctx->>'ab_test_id')::uuid AND arm=ctx->>'ab_arm' AND subscriber_id=sid AND revoked_at IS NULL) THEN RETURN false; END IF;
  -- A real opt-out, disabled contact or expression non-match is ineligible;
  -- source/runtime/context failure above must never be represented as zero.
  IF NOT EXISTS(SELECT 1 FROM public.subscribers s WHERE s.id=sid AND s.status::text='enabled') THEN RETURN false; END IF;
  SELECT coalesce(array_agg(sl.list_id),ARRAY[]::integer[]) INTO consented FROM public.subscriber_lists sl
   WHERE sl.subscriber_id=sid AND ctx->'list_ids' @> to_jsonb(sl.list_id)
    AND (sl.status::text='confirmed' OR (sl.status::text='unconfirmed' AND ctx->'single_list_ids' @> to_jsonb(sl.list_id)));
  IF NOT (ctx->>'base_list_id')::integer=ANY(consented) THEN RETURN false; END IF;
  matched:=crm_audience_v2.selection_regular_rule_match(ctx#>'{definition,rule}',consented,sid,ctx->>'brand');
  IF matched IS NULL THEN RAISE EXCEPTION USING ERRCODE='55000',MESSAGE='SEGMENT_SELECTION_UNAVAILABLE'; END IF;
  RETURN matched;
 END $fn$;

CREATE OR REPLACE FUNCTION crm_audience_v2.selection_worker_context(cid integer) RETURNS jsonb
 LANGUAGE plpgsql STABLE SECURITY INVOKER SET search_path=pg_catalog AS $fn$
 DECLARE ctx jsonb;
 BEGIN
  ctx:=crm_audience_v2.selection_context(cid,'084a9493713b21b618d24daae98b38db59fb84febf0c367914bea1ed7aa84c2d',true);
  IF ctx IS NULL THEN RAISE EXCEPTION USING ERRCODE='55000',MESSAGE='SEGMENT_SELECTION_UNAVAILABLE'; END IF;
  IF ctx->'bound'='true'::jsonb THEN
   SELECT ctx||jsonb_build_object('list_ids',jsonb_agg(DISTINCT pin->'list_id'),
    'single_list_ids',coalesce(jsonb_agg(DISTINCT pin->'list_id') FILTER(WHERE pin->>'optin'='single'),'[]'::jsonb))
   INTO ctx FROM jsonb_array_elements(ctx->'list_pins') pin;
  END IF;
  RETURN crm_audience_v2.ab_regular_context(cid,ctx);
 END $fn$;

CREATE OR REPLACE FUNCTION crm_audience_v2.campaign_send_guard() RETURNS trigger
 LANGUAGE plpgsql VOLATILE SECURITY DEFINER SET search_path=pg_catalog AS $fn$
 DECLARE brand text;ctl crm_audience_v2.regular_delivery_campaign%ROWTYPE;
 deployment crm_audience_v2.regular_worker_deployment%ROWTYPE;lease crm_audience_v2.regular_worker_lease%ROWTYPE;
 ctx jsonb;at timestamptz;
 progress text[]:=ARRAY['status','sent','to_send','max_subscriber_id','last_subscriber_id','started_at','updated_at'];
 BEGIN
  SELECT b.brand INTO brand FROM crm_audience_v2.campaign_binding_effective(OLD.id) b;
  IF NOT FOUND THEN
   IF TG_OP='DELETE' AND EXISTS(SELECT 1 FROM crm_audience_v2.campaign_binding WHERE campaign_id=OLD.id) THEN
    RAISE EXCEPTION 'SEGMENT_CAMPAIGN_HISTORY_RETAINED';
   END IF;
   IF TG_OP='DELETE' THEN RETURN OLD; END IF;RETURN NEW;
  END IF;
  IF TG_OP='DELETE' OR NEW.id IS DISTINCT FROM OLD.id
   OR NEW.type::text IS DISTINCT FROM 'regular' OR NEW.messenger IS DISTINCT FROM 'email'
   OR NEW.attribs#>>'{crm,policy}' IS DISTINCT FROM 'crm-campaign-v1'
   OR NEW.attribs#>>'{crm,brand}' IS DISTINCT FROM brand THEN
   RAISE EXCEPTION 'SEGMENT_CAMPAIGN_OPERATION_REQUIRED';
  END IF;
  -- Preserve draft editing under the existing campaign editor guard. A change
  -- invalidates any previously captured material; it never refreshes approval.
  IF OLD.status::text='draft' AND NEW.status::text='draft' THEN
   IF NEW.sent IS DISTINCT FROM 0 OR NEW.started_at IS NOT NULL
    OR NEW.last_subscriber_id IS DISTINCT FROM 0 THEN RAISE EXCEPTION 'SEGMENT_CAMPAIGN_OPERATION_REQUIRED'; END IF;
   RETURN NEW;
  END IF;
  IF (to_jsonb(NEW)-progress) IS DISTINCT FROM (to_jsonb(OLD)-progress) THEN
   RAISE EXCEPTION 'SEGMENT_CAMPAIGN_MATERIAL_LOCKED';
  END IF;
  IF OLD.status::text='draft' AND NEW.status::text='cancelled'
   AND (to_jsonb(NEW)-ARRAY['status','updated_at'])=(to_jsonb(OLD)-ARRAY['status','updated_at'])
   AND EXISTS(SELECT 1 FROM public.crm_ab_arm_v2 a JOIN public.crm_ab_experiment_v2 x ON x.test_id=a.test_id
    JOIN crm_audience_v2.ab_regular_lifecycle_intent i ON i.test_id=x.test_id AND i.version=x.version
    WHERE a.campaign_id=OLD.id AND x.state='prepared' AND i.action='cancel' AND i.created_xid=pg_current_xact_id()) THEN RETURN NEW; END IF;
  -- Halt is always possible, including when source, lease or control is lost.
  -- It cannot acknowledge recipients or alter count/max/start metadata.
  IF OLD.status::text IN('scheduled','running','paused') AND NEW.status::text IN('paused','cancelled')
   AND (to_jsonb(NEW)-ARRAY['status','updated_at'])=(to_jsonb(OLD)-ARRAY['status','updated_at']) THEN
   UPDATE crm_audience_v2.regular_delivery_campaign SET suspended=true WHERE campaign_id=OLD.id;
   RETURN NEW;
  END IF;
  SELECT * INTO ctl FROM crm_audience_v2.regular_delivery_campaign WHERE campaign_id=OLD.id;
  IF NOT FOUND OR NEW.sent IS DISTINCT FROM ctl.acknowledged_sent
   OR NEW.last_subscriber_id IS DISTINCT FROM ctl.acknowledged_subscriber_id THEN
   RAISE EXCEPTION 'SEGMENT_CAMPAIGN_RECEIPT_REQUIRED';
  END IF;
  -- Only private claim/finish/recovery can move that checkpoint. Legacy batch
  -- and cleanup updates cannot create progress by assigning native counters.
  -- Record completed history even after OFF/pause without creating authority.
  IF NEW.status=OLD.status AND NEW.to_send IS NOT DISTINCT FROM OLD.to_send
   AND NEW.max_subscriber_id IS NOT DISTINCT FROM OLD.max_subscriber_id
   AND NEW.started_at IS NOT DISTINCT FROM OLD.started_at THEN RETURN NEW; END IF;
  IF NOT ctl.enabled OR ctl.suspended OR ctl.material IS DISTINCT FROM crm_audience_v2.regular_delivery_material(OLD.id)
   OR NOT EXISTS(SELECT 1 FROM crm_audience_v2.campaign_binding_effective(OLD.id) b
    WHERE b.binding_version=ctl.binding_version AND b.binding_hash=ctl.binding_hash) THEN
   RAISE EXCEPTION 'SEGMENT_CAMPAIGN_OPERATION_UNAVAILABLE';
  END IF;
  -- Do not acquire deployment/lease row locks after the native campaign lock.
  -- The admission and SMTP paths own their stronger, ordered transaction locks.
  -- This trigger checks lifecycle state; it never authorizes transport.
  SELECT * INTO deployment FROM crm_audience_v2.regular_worker_deployment WHERE singleton;
  SELECT * INTO lease FROM crm_audience_v2.regular_worker_lease WHERE singleton;
  at:=clock_timestamp();
  IF deployment.singleton IS NULL OR NOT deployment.enabled OR deployment.approved_at>at
   OR deployment.worker_sha256 IS DISTINCT FROM ctl.worker_sha256
   OR deployment.runtime_sha256 IS DISTINCT FROM ctl.runtime_sha256
   OR lease.instance_id IS NULL OR lease.suspended OR lease.heartbeat_at>at OR lease.expires_at<=at
   OR lease.worker_sha256 IS DISTINCT FROM ctl.worker_sha256 OR lease.runtime_sha256 IS DISTINCT FROM ctl.runtime_sha256
   OR lease.database_role IS DISTINCT FROM deployment.database_role THEN
   RAISE EXCEPTION 'SEGMENT_CAMPAIGN_WORKER_UNAVAILABLE';
  END IF;
  ctx:=crm_audience_v2.selection_worker_context(OLD.id);
  IF ctx->'bound' IS DISTINCT FROM 'true'::jsonb THEN RAISE EXCEPTION 'SEGMENT_CAMPAIGN_OPERATION_UNAVAILABLE'; END IF;
  IF OLD.status::text='draft' AND NEW.status::text='scheduled'
   AND NEW.sent=0 AND NEW.last_subscriber_id=0 AND NEW.started_at IS NULL THEN RETURN NEW; END IF;
  IF OLD.status::text IN('scheduled','running') AND NEW.status::text='running' AND OLD.send_at<=at THEN RETURN NEW; END IF;
  IF OLD.status::text='paused' AND NEW.status::text='scheduled' THEN RETURN NEW; END IF;
  IF OLD.status::text='running' AND NEW.status::text='finished' THEN
   IF EXISTS(SELECT 1 FROM public.shrigma_email_dispatch d WHERE d.flow='campaign'
    AND d.piece='audience-regular-v1:'||OLD.id::text AND d.transport_state IN('in_flight','outcome_unknown'))
    OR EXISTS(SELECT 1 FROM public.subscriber_lists sl WHERE sl.list_id=(ctx->>'base_list_id')::integer
     AND sl.subscriber_id>NEW.last_subscriber_id AND sl.subscriber_id<=NEW.max_subscriber_id
     AND crm_audience_v2.selection_regular_matches(ctx,sl.subscriber_id)) THEN
    RAISE EXCEPTION 'SEGMENT_CAMPAIGN_FINALIZE_UNAVAILABLE';
   END IF;
   RETURN NEW;
  END IF;
  RAISE EXCEPTION 'SEGMENT_CAMPAIGN_OPERATION_REQUIRED';
 END
 $fn$;

CREATE FUNCTION crm_audience_v2.ab_regular_context(cid integer,ctx jsonb) RETURNS jsonb
 LANGUAGE plpgsql STABLE SECURITY INVOKER SET search_path=pg_catalog AS $fn$
 DECLARE p crm_audience_v2.ab_regular_pair%ROWTYPE;e public.crm_ab_experiment_v2%ROWTYPE;
  a public.crm_ab_arm_v2%ROWTYPE;s crm_audience_v2.ab_scope%ROWTYPE;
 BEGIN
  SELECT * INTO a FROM public.crm_ab_arm_v2 WHERE campaign_id=cid;
  IF NOT FOUND THEN RETURN ctx; END IF;
  SELECT * INTO s FROM crm_audience_v2.ab_scope WHERE test_id=a.test_id;
  -- A legacy A/B campaign must never fall through to this different emitter.
  IF NOT FOUND OR ctx->'bound' IS DISTINCT FROM 'true'::jsonb THEN
   RAISE EXCEPTION USING ERRCODE='55000',MESSAGE='AB_REGULAR_SCOPE_UNAVAILABLE';
  END IF;
  SELECT * INTO p FROM crm_audience_v2.ab_regular_pair WHERE test_id=a.test_id;
  SELECT * INTO e FROM public.crm_ab_experiment_v2 WHERE test_id=a.test_id;
  IF p.test_id IS NULL OR p.brand IS DISTINCT FROM ctx->>'brand' OR p.scope_hash IS DISTINCT FROM s.scope_hash
   OR (a.arm='a' AND p.campaign_a<>cid) OR (a.arm='b' AND p.campaign_b<>cid)
   OR NOT(e.state='scheduled' AND e.transport_bound OR e.state='prepared' AND p.admitted_xid=pg_current_xact_id())
   OR (SELECT count(*) FROM crm_audience_v2.regular_delivery_campaign WHERE campaign_id IN(p.campaign_a,p.campaign_b) AND enabled AND NOT suspended)<>2
   OR EXISTS(SELECT 1 FROM public.campaigns WHERE id IN(p.campaign_a,p.campaign_b) AND status::text IN('paused','cancelled'))
   OR EXISTS(SELECT 1 FROM public.shrigma_email_dispatch WHERE flow='campaign'
    AND piece IN('audience-regular-v1:'||p.campaign_a::text,'audience-regular-v1:'||p.campaign_b::text) AND transport_state='outcome_unknown') THEN
   RAISE EXCEPTION USING ERRCODE='55000',MESSAGE='AB_REGULAR_PAIR_UNAVAILABLE';
  END IF;
  RETURN ctx||jsonb_build_object('ab_test_id',p.test_id,'ab_arm',a.arm,'ab_scope_hash',p.scope_hash);
 END $fn$;

CREATE FUNCTION crm_audience_v2.selection_shopify_rule(rule jsonb,sid integer,b text,source_config jsonb) RETURNS jsonb
LANGUAGE plpgsql STABLE SECURITY INVOKER SET search_path=pg_catalog AS $fn$
DECLARE pin text; cfg crm_audience_v2.shopify_source%ROWTYPE; matched boolean;
BEGIN
 IF NOT crm_audience_v2.shopify_rule_valid(rule) THEN RETURN NULL; END IF;
 pin:=crm_audience_v2.shopify_source_hash(b,rule->>'field',source_config);
 SELECT * INTO cfg FROM crm_audience_v2.shopify_source WHERE brand=b;
 IF NOT FOUND OR NOT cfg.enabled OR pin IS NULL OR cfg.field_hashes->>(rule->>'field') IS DISTINCT FROM pin
  OR crm_audience_v2.shopify_snapshot(b)->'current' IS DISTINCT FROM 'true'::jsonb
  OR (SELECT count(*) FROM jsonb_array_elements(source_config->'fields') f WHERE f->>'key'=rule->>'field'
   AND f->'available'='true'::jsonb AND f->>'source_hash'=pin)<>1 THEN RETURN NULL; END IF;
 IF rule->>'field'='purchase.product' AND (SELECT count(*) FROM jsonb_array_elements(source_config->'products') p
  WHERE p->>'id'=rule->>'value' AND p->>'brand'=b AND p->'available'='true'::jsonb)<>1 THEN RETURN NULL; END IF;
 -- sid=0 validates context only. Individual unknown facts never become false.
 matched:=CASE WHEN sid=0 THEN false ELSE crm_audience_v2.shopify_customer_match(rule,sid,b,pin) END;
 RETURN jsonb_build_object('match',matched,'nodes',1,'pins',jsonb_build_array(jsonb_build_object(
  'rule_key','{"op":"condition","field":'||to_jsonb(rule->>'field')::text||',"operator":'||to_jsonb(rule->>'operator')::text||',"value":'||(rule->'value')::text||'}',
  'source','shopify','source_hash',pin,'shop_id',cfg.shop_id,'currency',cfg.currency,'timezone',cfg.timezone)));
END $fn$;

CREATE OR REPLACE FUNCTION crm_audience_v2.shopify_rule_valid(rule jsonb) RETURNS boolean
LANGUAGE plpgsql IMMUTABLE SECURITY INVOKER SET search_path=pg_catalog AS $fn$
BEGIN
 IF jsonb_typeof(rule) IS DISTINCT FROM 'object' OR rule->>'op' IS DISTINCT FROM 'condition'
  OR NOT(rule ?& ARRAY['op','field','operator','value']) OR rule-'op'-'field'-'operator'-'value'<>'{}'::jsonb THEN RETURN false; END IF;
 IF rule->>'field'='purchase.product' THEN
  RETURN coalesce(jsonb_typeof(rule->'value')='string' AND rule->>'value' ~ '^gid://shopify/Product/[1-9][0-9]{0,19}$'
   AND rule->>'operator' IN('purchased','not_purchased'),false);
 END IF;
 IF rule->>'field' IN('purchase.count','purchase.amount') THEN
  IF rule->>'operator' IS NULL OR rule->>'operator' NOT IN('eq','gt','gte','lt','lte') THEN RETURN false; END IF;
  IF rule->>'field'='purchase.count' THEN
   RETURN jsonb_typeof(rule->'value')='number' AND rule->>'value' ~ '^(0|[1-9][0-9]{0,9})$'
    AND (rule->>'value')::numeric<=2147483647;
  END IF;
  RETURN jsonb_typeof(rule->'value')='string' AND rule->>'value' ~ '^(0|[1-9][0-9]{0,11})\.[0-9]{2}$';
 END IF;
 IF rule->>'field'='purchase.last_date' THEN
  IF jsonb_typeof(rule->'value') IS DISTINCT FROM 'string' OR rule->>'value' !~ '^[0-9]{4}-[0-9]{2}-[0-9]{2}$'
   OR rule->>'value'<'2000-01-01' OR rule->>'value'>'2100-12-31' OR rule->>'operator' IS NULL
   OR rule->>'operator' NOT IN('eq','before','on_or_before','after','on_or_after') THEN RETURN false; END IF;
  PERFORM (rule->>'value')::date;RETURN true;
 END IF;
 RETURN false;
EXCEPTION WHEN invalid_datetime_format OR datetime_field_overflow OR invalid_text_representation THEN RETURN false;
END
$fn$;

CREATE OR REPLACE FUNCTION crm_audience_v2.shopify_customer_match(rule jsonb,sid integer,b text,pin text) RETURNS boolean
LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path=pg_catalog AS $fn$
DECLARE cfg crm_audience_v2.shopify_source%ROWTYPE;f crm_audience_v2.shopify_customer_fact%ROWTYPE;
 value_number numeric;target_number numeric;value_date date;target_date date;product_fact crm_audience_v2.shopify_customer_product%ROWTYPE;
BEGIN
 IF NOT crm_audience_v2.shopify_rule_valid(rule) OR sid IS NULL OR sid<1 OR b IS NULL OR b NOT IN('fish','aristo') THEN RETURN NULL; END IF;
 SELECT * INTO cfg FROM crm_audience_v2.shopify_source WHERE brand=b;
 IF NOT FOUND OR NOT cfg.enabled OR pin IS NULL OR cfg.field_hashes->>(rule->>'field') IS DISTINCT FROM pin
  OR crm_audience_v2.shopify_snapshot(b)->'current' IS DISTINCT FROM 'true'::jsonb THEN RETURN NULL; END IF;
 SELECT x.* INTO f FROM crm_audience_v2.shopify_customer_fact x
 JOIN public.subscribers s ON s.id=x.subscriber_id AND s.uuid=x.subscriber_uuid AND lower(btrim(s.email))=x.email
 JOIN crm_audience_v2.shopify_identity i ON i.brand=x.brand AND i.customer_gid=x.customer_gid
  AND i.subscriber_id=x.subscriber_id AND i.subscriber_uuid=x.subscriber_uuid
 WHERE x.brand=b AND x.operation_id=cfg.current_operation AND x.subscriber_id=sid AND x.identity_state='resolved';
 IF NOT FOUND THEN RETURN NULL; END IF;
 IF rule->>'field'='purchase.product' THEN
  SELECT p.* INTO product_fact FROM crm_audience_v2.shopify_customer_product p
  JOIN crm_audience_v2.shopify_product_batch t ON t.brand=p.brand AND t.operation_id=p.operation_id AND t.ready
  WHERE p.brand=b AND p.operation_id=cfg.current_operation AND p.customer_gid=f.customer_gid;
  IF NOT FOUND THEN RETURN NULL; END IF;
  IF EXISTS(SELECT 1 FROM jsonb_array_elements(product_fact.products) p WHERE p->>'id'=rule->>'value') THEN
   RETURN rule->>'operator'='purchased';
  END IF;
  IF NOT product_fact.history_complete OR (f.orders_count=0 AND (f.last_order_at IS NOT NULL OR f.amount_spent>0)) OR EXISTS(SELECT 1 FROM crm_audience_v2.shopify_product_history_gap g WHERE g.brand=product_fact.brand AND g.operation_id=product_fact.operation_id AND g.customer_gid=product_fact.customer_gid) THEN RETURN NULL; END IF;
  RETURN rule->>'operator'='not_purchased';
 END IF;
 -- A contradictory zero cannot prove that no order exists. Historical orders
 -- may predate the surviving Customer after a merge or import.
 IF f.orders_count=0 AND (f.last_order_at IS NOT NULL OR f.amount_spent>0) THEN RETURN NULL; END IF;
 IF rule->>'field'='purchase.last_date' THEN
  IF f.last_order_at IS NULL THEN RETURN CASE WHEN f.orders_count=0 THEN false ELSE NULL END; END IF;
  value_date:=(f.last_order_at AT TIME ZONE cfg.timezone)::date;target_date:=(rule->>'value')::date;
  RETURN CASE rule->>'operator' WHEN 'eq' THEN value_date=target_date WHEN 'before' THEN value_date<target_date
   WHEN 'on_or_before' THEN value_date<=target_date WHEN 'after' THEN value_date>target_date WHEN 'on_or_after' THEN value_date>=target_date END;
 END IF;
 value_number:=CASE rule->>'field' WHEN 'purchase.count' THEN f.orders_count WHEN 'purchase.amount' THEN f.amount_spent END;
 target_number:=(rule->>'value')::numeric;
 RETURN CASE rule->>'operator' WHEN 'eq' THEN value_number=target_number WHEN 'gt' THEN value_number>target_number
  WHEN 'gte' THEN value_number>=target_number WHEN 'lt' THEN value_number<target_number WHEN 'lte' THEN value_number<=target_number END;
END
$fn$;

CREATE FUNCTION crm_audience_v2.selection_recorded_origin_rule(rule jsonb,sid integer,b text,source_config jsonb) RETURNS jsonb
LANGUAGE plpgsql STABLE SET search_path=pg_catalog AS $fn$
DECLARE o jsonb; pin text; field_hash text; matched boolean;
BEGIN
 IF NOT crm_audience_v2.recorded_origin_rule_valid(rule) THEN RETURN NULL; END IF;
 field_hash:=crm_audience_v2.recorded_origin_source_hash(b);
 IF field_hash IS NULL OR (SELECT count(*) FROM jsonb_array_elements(source_config->'fields') f
  WHERE f->>'key'='signup.recorded_origin' AND f->'available'='true'::jsonb AND f->>'source_hash'=field_hash)<>1 THEN RETURN NULL; END IF;
 IF (SELECT count(*) FROM jsonb_array_elements(source_config->'recorded_origins') v
  WHERE v->>'key'=rule->>'value' AND v->>'brand'=b AND v->'available'='true'::jsonb)<>1 THEN RETURN NULL; END IF;
 SELECT v INTO o FROM jsonb_array_elements(source_config->'recorded_origins') v WHERE v->>'key'=rule->>'value';
 pin:=o->>'provenance_hash';
 IF NOT crm_audience_v2.recorded_origin_source_current(b,rule->>'value',pin) THEN RETURN NULL; END IF;
 matched:=CASE WHEN sid=0 THEN false ELSE crm_audience_v2.recorded_origin_match(rule,sid,b,pin) END;
 RETURN jsonb_build_object('match',matched,'nodes',1,'pins',jsonb_build_array(jsonb_build_object(
  'rule_key','{"op":"condition","field":"signup.recorded_origin","operator":"is","value":'||to_jsonb(rule->>'value')::text||'}',
  'source','crm','source_hash',field_hash,'recorded_origin_provenance_hash',pin)));
END $fn$;

